DROP TABLE IF EXISTS `metal_detector_checks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `metal_detector_checks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `inspection_date` date NOT NULL,
  `shift` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employee_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employee_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `building` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `guard_post` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scanner_brand` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone1_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone2_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone3_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone4_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone5_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone6_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submitted_by_id` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) DEFAULT '0',
  `deleted_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `submitted_by_id` (`submitted_by_id`),
  CONSTRAINT `metal_detector_checks_ibfk_1` FOREIGN KEY (`submitted_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1366 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
