--
-- Table structure for table `reports`
--

DROP TABLE IF EXISTS `reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reports` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `report_date` date NOT NULL,
  `employee_id` varchar(8) COLLATE utf8mb4_general_ci NOT NULL,
  `full_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `shift` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `building` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `guard_post` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `report_time` time NOT NULL,
  `incident_report` text COLLATE utf8mb4_general_ci NOT NULL,
  `special_incident` text COLLATE utf8mb4_general_ci,
  `emergency_incident` text COLLATE utf8mb4_general_ci,
  `updated_by` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_by` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT '0',
  `submission_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25822 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
