INSERT INTO `reports` VALUES (2343,'2026-01-31','10591359','จิราภร เพชรมุณี','ดึก','2','D1','20:01:00','เวลา 20.00 นเวลานี้ดิฉันเข้าประจำจุด d1 ตึก 2 ค่ะเวลานี้มีแม่บ้านนำขยะมาทิ้งเป็นระยะๆพร้อมชั่งน้ำหนักดิชั้นลงบันทึกเรียบร้อยดีค่ะ','','',NULL,NULL,NULL,NULL,0,'2026-01-31 13:02:04'),(2344,'2026-01-31','50016303','บุญทัน คงสิบ','ดึก','6','6/1','20:01:00','ช่วงเวลานี้ได้ตรวจพนักงานตรวจกระเป๋าผ่านตู้สแกนเป็นระยะตั้งแต่เวลา 19:00 น ถึง 20:00 น เหตุการณ์ปกติ','','',NULL,NULL,NULL,NULL,0,'2026-01-31 13:02:50'),(2345,'2026-01-31','20043907','น้ำทิพย์ กลิ่นจันทร์','ดึก','4','Customs Park 2','20:02:00','เวลานี้ได้ทำการ คอยสังเกตการณ์และได้ทำการตามรถเข้าช่องลานจอด และ ตรวจพื้นที่ไม่พบสิ่งใดผิดปกติ','','',NULL,NULL,NULL,NULL,0,'2026-01-31 13:03:28'),(2346,'2026-01-31','20006335','ฐิติวัฒน์ ขีดขิน','ดึก','4','Traffic Receiving','20:00:00','ช่วงเวลา​ 19.00-20.00​ น.​ เข้า​รับหน้าที่​ต่อจาก​คู่​ผลัด​กะ​เช้า​ อุปกรณ์​พร้อม​ใช้​ ท​ำ​หน้าที่​การจราจร​อยู่​บริเวณ​หน้า​เกรด​2​ และ​สามแยก​พระพรหม​ ปล่อย​รถบัส​ออกจาก​ลานจอด​เสร็จ​ รับ​กุญแจ​ที่​เกรด​5​ คอย​ไขกุญแจ​ให้​รถ​ เหตุการณ์​90​','','',NULL,NULL,NULL,NULL,0,'2026-01-31 13:04:06'),(2347,'2026-01-31','10502898','ทัศนา พันธุ์เมฆ','ดึก','4','Gate 5','20:04:00','รายงานเหตุการณ์ช่วงเวลา 19:00 น.- 20:00 น. เข้าปฏิบัติหน้าที่ต่อจากกะเช้าสอบถามเหตุการณ์และอุปกรณ์ 90 ค่ะ อุปกรณ์พร้อมใช้งานและอ่าน JD รับทราบ scan QR code ตรวจเช็คอุปกรณ์ประจำจุดรักษาการณ์  scan  check handheld ประจำจุดรักษาการณ์   ตรวจพนักงานออกจากตึกออกกะด้วยไม้ scan handheld ไม่พบสิ่งผิดปกติใดๆ  รถงานเข้าส่งงาน-รับงานตรวจวัดแอลกอฮอล์ก่อนเข้าและ scan QR code ข้อปฏิบัติการเข้าจอดภายในพื้นที่บริษัทตรวจค้นรถแจ้งจราจรรับทราบเปิดไม้กระดกให้รถงานเข้าส่งงาน-รับงาน รถงานบริษัท PGC เข้ารับ smock ตรวจวัดแอลกอฮอล์และ scan QR code ข้อปฏิบัติการเข้าจอดภายในพื้นที่บริษัทตรวจค้นรถแจ้งจราจรรับทราบเปิดไม้กระดกให้รถงาน PGC เข้ารับ smock  รถงานปราจีนเข้าส่งงานตรวจวัดแอลกอฮอล์ก่อนเข้าและ scan QR code ข้อปฏิบัติการเข้าจอดภายในพื้นที่บริษัทตรวจค้นรถจดบันทึก seal และกล่องดำลงในสมุดบันทึก seal แ