INSERT INTO `reports` VALUES (18647,'2026-02-26','10456627','วันเพ็ญ อ่ำสำอางค์','ดึก','4','Scan Link way','06:00:00','เวลานี้ก็คอยสังเกตการณ์ตรวจพนักงานผ่านตู้สแกนเป็นระยะ ตรวจเช็คงาน 3.5 จำนวน 50 pcs ไปแลปตึก2  รัดสายเข็มขัดและลงบันทึกไว้เรียบร้อยแจ้งปลายทางรับทราบ','ไม่มี','ไม่มี',NULL,NULL,NULL,NULL,0,'2026-02-26 23:03:44'),(18648,'2026-02-26','10558952','จารุพร การะเกษ','ดึก','2','A3','06:04:00','เวลา 05.00 นถึง 06.00 นสรุปเหตุการณ์โดยรวม 12 ชั่วโมงที่ผ่านมาเหตุการณ์ปกติค่ะ','','',NULL,NULL,NULL,NULL,0,'2026-02-26 23:04:38'),(18649,'2026-02-26','10502071','วไรพร ชุมศรี','ดึก','6','6/1','06:04:00','รายงานเหตุการณ์ 05.00 น. ถึง 06.00 น เวลานี้ พนักงาน ออกมาทำธุระส่วนตัว ผ่านตู้สแกน ตรวจกระเป๋าสัมภาระต่างๆ กะเช้าบางคนก็ทยอยเข้ามา เหตุการณ์เรียบร้อยปกติค่ะ','','',NULL,NULL,NULL,NULL,0,'2026-02-26 23:05:12'),(18650,'2026-02-26','50016303','บุญทัน คงสิบ','ดึก','3','EIXT INSPECTION (ทางออก)','06:06:00','ช่วงเวลานี้ได้ตรวจพนักงานตรวจกระเป๋าตรวจแม่บ้านผ่านโต๊ะสแกนเป็นระยะตั้งแต่เวลา 05.00นถึง 06:00 น ไม่พบสิ่งผิดปกติใดๆเหตุการณ์ปกติ','','',NULL,NULL,NULL,NULL,0,'2026-02-26 23:08:15'),(18651,'2026-02-26','10540492','พัชรินทร์ อินทร์ฉ่ำ','ดึก','4','Gate 1','06:03:00','ช่วงเวลานี้ 05.00 นถึง 06.00 นตรวจสอบแลกบัตรผู้มาติดต่อส่งของร้านค้า สแกนบัตรEvams แม่บ้าน.รปภ.ร้านค้า.เข้างานตรวจสอบแลกบัตรพนักงานลืมบัตร สแกนบัตรยืมชูให้พนักงาน เหตุการณ์ทั่วไปโดยรวมปกติค่ะ','','',NULL,NULL,NULL,NULL,0,'2026-02-26 23:09:12'),(18652,'2026-02-26','10541644','กมลชนก สุขสว่าง','ดึก','6','6/2','06:08:00','เวลานี้น. 05.00-06.00น','ไม่มี','ไม่มีแต่คอยสังเกตการณ์พื้นที่รับผิดชอบไม่พบสิ่งผิดปกติใดๆมีแต่พนักงานเดินผ่านเข้าออกเป็นระยะค่ะ',NULL,NULL,NULL,NULL,0,'2026-02-26 23:09:57'),(18653,'2026-02-26','20040569','ทิพย์รัตน์ นพแก้ว','ดึก','2','A2','06:09:00','เวลานี้คอยสังเกตการณ์บริเวณจุดประจำการและมีแม่บ้านมาสแกนบัตรเข้างานเป็นระยะเหตุการณ์โดยรวมเรียบร้อยดีค่ะ','','',NULL,NULL,NULL,NULL,0,'2026-02-26 23:10:11'),(18654,'2026-02-26','10545207','ศรีจันทร์ นิกรสุข','ดึก','9','B9','06:07:00','ช่วงเวลา05